// Turn a Vikunja webhook into the broker's event shape and sign it (docs/n8n.md). Needs
// NODE_FUNCTION_ALLOW_BUILTIN=crypto and N8N_BLOCK_ENV_ACCESS_IN_NODE=false for $env.
// With VIKUNJA_WEBHOOK_SECRET set it also checks Vikunja's own X-Vikunja-Signature first.
const crypto = require('crypto');
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const raw = await this.helpers.getBinaryDataBuffer(i, 'data');
  if ($env.VIKUNJA_WEBHOOK_SECRET) {
    const want = crypto.createHmac('sha256', $env.VIKUNJA_WEBHOOK_SECRET).update(raw).digest('hex');
    const got = String(item.json.headers['x-vikunja-signature'] || '');
    if (want.length !== got.length || !crypto.timingSafeEqual(Buffer.from(want), Buffer.from(got))) {
      throw new Error('bad X-Vikunja-Signature');
    }
  }
  const hook = JSON.parse(raw.toString('utf8'));
  const data = hook.data || {};
  const task = data.task || {};
  const evt = {
    source: 'vikunja',
    event_name: hook.event_name,
    task_id: task.id,
    project_id: task.project_id,
    done: task.done === true,
    doer: (data.doer || {}).username || null,
    labels: (task.labels || []).map(l => l.title),
    assignees: (task.assignees || []).map(a => a.username),
  };
  if (data.comment) {
    evt.comment = data.comment.comment || '';
    evt.comment_id = data.comment.id;
    const m = /broker-run:([A-Za-z0-9_-]+)/.exec(evt.comment);   // the broker's own comments carry this marker
    if (m) evt.run_id = m[1];
  }
  const body = JSON.stringify(evt);
  const sig = crypto.createHmac('sha256', $env.EPH_BROKER_HMAC_SECRET).update(body).digest('hex');
  out.push({ json: { body, sig } });
}
return out;
